<template>
  <Collapsible
    v-if="isCollapsibleGroup"
    v-slot="{ open }"
    :default-open="isActive(page)"
    class="flex w-full min-w-0 flex-col gap-1 transition duration-300 hover:bg-accent/40"
  >
    <CollapsibleTrigger class="w-full">
      <AppSidebarItemBasic :page :open :depth="depth" @click="emit('click', $event)" />
    </CollapsibleTrigger>
    <CollapsibleContent v-if="isCollapsibleGroup" class="flex w-full min-w-0 flex-col gap-1">
      <AppSidebarItem
        v-for="child in page.children"
        :key="child.name"
        :page="child"
        :depth="depth + 1"
        @click="emit('click', $event)"
      />
    </CollapsibleContent>
  </Collapsible>
  <AppSidebarItemBasic v-else :page :depth="depth" @click="emit('click', $event)" />
</template>

<script setup lang="ts">
const isDesktop = useMediaQuery('(min-width: 1024px)');

const { page, depth = 0 } = defineProps<{
  page: Page;
  depth?: number;
}>();

const isCollapsibleGroup = computed(() => !!page.children && !page.isSlideOver && isDesktop.value);

const emit = defineEmits<{ click: [page: Page] }>();

const { isActive } = useNavActive();
</script>
