<template>
  <section v-if="isVisible && problem">
    <Alert variant="destructive" class="flex flex-col sm:flex-row justify-center gap-2 sm:gap-4 bg-card w-fit mx-auto">
      <div class="flex items-center gap-2">
        <TriangleAlert class="size-5" />
        <AlertTitle class="w-fit mb-0 leading-5">{{ problem.title }}. {{ problem.subtitle }}</AlertTitle>
      </div>
      <NuxtLink v-if="problem.to" :to="problem.to">
        <Button variant="outline" size="sm">Add Information</Button>
      </NuxtLink>
    </Alert>
  </section>
</template>

<script setup lang="ts">
import { accountProblems, getAccountProblem } from '~/constants/accountProblems';
import { TriangleAlert } from 'lucide-vue-next';

const { accountProblems: accountProblemsData } = useUserRole();

const problem = computed(() =>
  accountProblemsData.value?.banner_alert ? getAccountProblem(accountProblemsData.value?.banner_alert) : null
);

const isVisible = computed(() => {
  const allRoutes = useRouter().getRoutes();
  const currentRoute = useRoute().name;
  const isCurrentRouteExists = allRoutes.some((route) => route.name === currentRoute);
  if (!isCurrentRouteExists) return false;

  const accountProblemsRoutes = Object.values(accountProblems).find((problem) => problem.to?.name === useRoute().name);
  return !accountProblemsRoutes;
});
</script>

<style scoped lang="scss"></style>
