<template>
  <DropdownMenu v-model:open="isOpen">
    <DropdownMenuTrigger as-child>
      <SidebarMenuButton
        class="w-full h-12 flex items-center gap-2 group-data-[collapsible=icon]:!p-0 group-data-[collapsible=icon]:justify-center group-data-[collapsible=icon]:overflow-visible"
        aria-label="Account menu"
        data-testid="sidebar-profile-trigger"
      >
        <UserProfileInfo
          :hide-text-when-collapsed="true"
          :notification-count="isOpen ? undefined : notificationCount"
          :problem-count="isOpen ? undefined : accountProblemCount"
        />
      </SidebarMenuButton>
    </DropdownMenuTrigger>
    <DropdownMenuContent side="right" align="end" class="w-56">
      <DropdownMenuItem data-testid="sidebar-account" @click="navigateTo({ name: 'account' })">
        <UserRoundIcon class="h-4 w-4" />
        <span>My Account</span>
        <Badge v-if="accountProblemCount" class="ml-auto w-4 h-4 p-0 flex justify-center" variant="destructive">
          <span class="text-[10px]/[14px]">{{ accountProblemCount }}</span>
        </Badge>
      </DropdownMenuItem>
      <DropdownMenuItem data-testid="sidebar-notifications" @click="navigateTo({ name: 'notifications' })">
        <BellIcon class="h-4 w-4" />
        <span>Notifications</span>
        <Badge v-if="notificationCount" class="ml-auto w-4 h-4 p-0 flex justify-center" variant="info">
          <span class="text-[10px]/[14px]">{{ notificationCount }}</span>
        </Badge>
      </DropdownMenuItem>
      <DropdownMenuSeparator />
      <DropdownMenuItem class="text-destructive focus:text-destructive" data-testid="sidebar-logout" @click="logOut">
        <LogOutIcon class="h-4 w-4" />
        <span>Log out</span>
      </DropdownMenuItem>
    </DropdownMenuContent>
  </DropdownMenu>
</template>

<script setup lang="ts">
import { BellIcon, LogOutIcon, UserRoundIcon } from 'lucide-vue-next';

interface Props {
  // Unread notification count (already formatted, e.g. '3' or '9+'); empty string when none.
  notificationCount?: string;
}

withDefaults(defineProps<Props>(), {
  notificationCount: undefined,
});

const isOpen = ref(false);

const { logOut } = useLogout();

const { accountProblems } = useUserRole();
// Account-alert count (e.g. incomplete profile). Surfaced as a destructive badge on the
// avatar and the "My Account" row so it stays visible after moving out of the main nav.
const accountProblemCount = computed(() => {
  const count = accountProblems.value?.alert_counters.account;
  return count ? count.toString() : '';
});
</script>

<style scoped lang="scss"></style>
