<template>
  <SidebarContent class="py-4 relative">
    <SidebarGroup class="p-0 pt-4 absolute inset-0 overflow-y-auto bg-background">
      <SidebarMenu>
        <AppSidebarItem v-for="page in sidebarPages" :key="page.name" :page @click="drillDown" />
      </SidebarMenu>
    </SidebarGroup>
    <TransitionGroup
      enter-active-class="transition-transform duration-200 ease-in-out"
      enter-from-class="translate-x-full"
      leave-active-class="transition-transform duration-200 ease-in-out"
      leave-to-class="translate-x-full"
    >
      <SidebarGroup
        v-for="slideOver in drillDownPointer"
        :key="slideOver.name"
        class="p-0 pt-4 absolute inset-0 overflow-y-auto bg-background"
      >
        <SidebarMenu>
          <SidebarMenuItem
            class="flex gap-2 items-center h-10 justify-center transition duration-300 hover:bg-accent/50"
          >
            <SidebarMenuButton class="pl-4 w-full whitespace-nowrap flex h-10" tooltip="Back" @click="drillUp">
              <div class="flex w-full items-center gap-2 min-w-0">
                <ChevronLeftIcon class="w-4 h-4 shrink-0" />
                <span class="text-sm font-medium overflow-hidden whitespace-nowrap text-ellipsis">Back</span>
                <Spinner v-if="slideOver.isLoading" class="ml-auto w-4 h-4 shrink-0" />
              </div>
            </SidebarMenuButton>
          </SidebarMenuItem>
          <AppSidebarItem v-for="page in slideOver.children" :key="page.name" :page @click="drillDown" />
        </SidebarMenu>
      </SidebarGroup>
    </TransitionGroup>
  </SidebarContent>
</template>

<script setup lang="ts">
import { ChevronLeftIcon } from 'lucide-vue-next';
import { Spinner } from '~/assets/icons';

interface Props {
  sidebarPages: Page[];
}

const props = defineProps<Props>();

const { getActiveChain } = useNavActive();

function findPage(pages: Page[], name: string): Page | undefined {
  for (const page of pages) {
    if (page.name === name) return page;
    if (page.children) {
      const found = findPage(page.children, name);
      if (found) return found;
    }
  }
  return undefined;
}

const hadInput = ref(false);
const drillStack = ref<string[]>([]);
const drillDownPointer = computed(() =>
  drillStack.value.map((name) => findPage(props.sidebarPages, name)).filter((page): page is Page => Boolean(page))
);

watch(
  () => props.sidebarPages,
  (pages) => {
    if (!hadInput.value) {
      drillStack.value = getActiveChain(pages)
        .filter((page) => page.isSlideOver)
        .map((page) => page.name);
    }
  },
  { immediate: true }
);

function drillDown(page: Page) {
  hadInput.value = true;
  if (page.isSlideOver && !drillStack.value.includes(page.name)) {
    drillStack.value = [...drillStack.value, page.name];
  }
}
function drillUp() {
  hadInput.value = true;
  drillStack.value = drillStack.value.slice(0, -1);
}
</script>
