<template>
  <AppSidebar>
    <template #main>
      <slot />
    </template>
  </AppSidebar>
</template>

<script setup lang="ts">
import { SplashScreen } from '@capacitor/splash-screen';
import * as Sentry from '@sentry/nuxt';
import * as SentryVue from '@sentry/vue';
import { SafeArea } from '@capacitor-community/safe-area';
import { Capacitor } from '@capacitor/core';

const feedback = Sentry.getFeedback();
let feedbackUnsubscribe: any | null = null;
const feedbackMobile = SentryVue.getFeedback();
let feedbackMobileUnsubscribe: any | null = null;
onMounted(async () => {
  await SplashScreen.hide();
  setTimeout(async () => {
    await SafeArea.enable({
      config: {
        customColorsForSystemBars: true,
        statusBarContent: 'dark',
        navigationBarContent: 'dark',
      },
    });
  }, 250);

  const reportABugButton = document.querySelector('#sentry_report_a_bug');
  if (!reportABugButton) {
    console.warn('Report a bug button not found in the DOM.');
  } else {
    feedbackUnsubscribe = feedback?.attachTo(reportABugButton, {});
  }
  const isNative = Capacitor.isNativePlatform();

  const reportABugButtonMobile = document.querySelector('#sentry_report_a_bug_mobile');
  if (!reportABugButtonMobile) {
    console.warn('Report a bug button for mobile not found in the DOM.');
  } else {
    if (isNative) feedbackMobileUnsubscribe = feedbackMobile?.attachTo(reportABugButtonMobile, {});
    else feedbackMobileUnsubscribe = feedback?.attachTo(reportABugButtonMobile, {});
  }
});

onBeforeUnmount(() => {
  feedbackUnsubscribe?.();
  feedbackMobileUnsubscribe?.();
});
</script>

<style scoped lang="scss"></style>
