import { useMobileRuntimeState } from '~/composables/mobile/useMobileRuntimeState';

export function useLogout() {
  const { signOut } = useAuth();
  const { isTracking, unsyncedShiftIds } = useMobileRuntimeState();
  const logoutBlocked = computed(() => isTracking.value || unsyncedShiftIds.value.length > 0);

  async function logOut() {
    if (logoutBlocked.value) {
      showToastError(
        isTracking.value
          ? "You're on a work shift. End the shift before logging out."
          : 'Please upload shift data before logging out.'
      );
      return;
    }
    await signOut();
  }

  return { logoutBlocked, logOut };
}
