<template>
  <footer id="mobile-menu" class="block sm:hidden fixed w-full bottom-0 left-0 bg-background z-50">
    <transition
      enter-from-class="translate-y-full opacity-0"
      leave-to-class="translate-y-full opacity-0"
      enter-active-class="transition-transform duration-300"
      leave-active-class="transition duration-300"
    >
      <div v-show="isMenuOpen" id="mobile-menu-popover" class="wrapper absolute -z-10 bottom-20 left-0 w-full">
        <div
          ref="rMenuExpanded"
          class="bg-accent-blind pt-2 rounded-t-xl shadow-[0px_-8px_24px_0px_#00000017] border-t"
          :style="{ transform: `translateY(${Math.max(currentY, 0)}px)` }"
          @touchstart.stop="onTouchStart"
          @touchmove.stop="onTouchMove"
          @touchend.stop="onTouchEnd"
        >
          <span class="bg-border w-12 h-1 rounded-sm block m-auto pb-1 cursor-pointer" />
          <div class="flex flex-col gap-1 pb-4">
            <div class="px-4 py-3" data-testid="mobile-menu-profile">
              <UserProfileInfo size="sm" />
            </div>
            <Separator />
            <NuxtLink
              v-for="page in menuExpanded"
              :key="page.name"
              class="flex items-center gap-2 h-12 w-full px-4 active:bg-secondary active:text-secondary-foreground"
              :class="
                cn({
                  'pointer-events-none opacity-50': page.disabled,
                  'bg-accent': page.to.name && route.name?.startsWith(page.to.name as string),
                })
              "
              :to="page.to"
              @click="closeMenu"
            >
              <div class="flex items-center gap-2">
                <component :is="page.icon" class="w-4 h-4" />
                <span class="text-sm leading-6 font-medium text-nowrap">{{ page.name }}</span>
              </div>
              <Badge v-if="page.problems" class="w-4 h-4 p-0 flex justify-center" variant="destructive">
                <span class="text-[10px]/[14px] xs:text-xs">{{ page.problems }}</span>
              </Badge>
              <Badge v-if="page.infoBadge" class="w-4 h-4 p-0 flex justify-center" variant="info">
                <span class="text-[10px]/[14px] xs:text-xs">{{ page.infoBadge }}</span>
              </Badge>
            </NuxtLink>
            <template v-if="hasMoreGroup">
              <NuxtLink
                class="flex items-center gap-2 h-12 w-full px-4 active:bg-secondary active:text-secondary-foreground"
                :class="
                  cn({
                    'bg-accent': route.name?.startsWith('tools'),
                  })
                "
                :to="{ name: 'tools' }"
                @click="closeMenu"
              >
                <EllipsisIcon class="w-4 h-4" />
                <span class="text-sm leading-6 font-medium">More Tools</span>
              </NuxtLink>
            </template>
            <Separator />
            <div
              id="sentry_report_a_bug_mobile"
              class="flex items-center gap-2 h-12 w-full px-4 cursor-pointer active:bg-secondary active:text-secondary-foreground"
            >
              <MegaphoneIcon class="h-4 w-4" />
              <span class="text-sm leading-6 font-medium">Report a Bug</span>
            </div>
            <div
              class="flex items-center gap-2 h-12 w-full px-4 cursor-pointer active:bg-secondary active:text-secondary-foreground"
              @click="logOut"
            >
              <LogOutIcon class="h-4 w-4" />
              <span class="text-sm leading-6 font-medium">Log out</span>
            </div>
            <VersionBadge class="w-full absolute bottom-0 p-2 block" />
          </div>
        </div>
      </div>
    </transition>
    <div class="grid grid-cols-4 h-20 items-center border border-t shadow-[0px_-4px_6px_0px_#00000017] bg-background">
      <NuxtLink
        v-for="page in menu"
        :key="page.name"
        class="flex flex-col gap-2 items-center h-full justify-center transition duration-300 active:bg-secondary active:text-secondary-foreground"
        :class="[
          page.to.name && route.name?.startsWith(page.to.name as string)
            ? 'bg-accent shadow-foreground shadow-[inset_0_-3px_0]'
            : '',
          page.disabled ? 'pointer-events-none opacity-50' : '',
        ]"
        :to="page.to"
        @click="closeMenu"
      >
        <div class="relative">
          <component :is="page.icon" class="w-6 h-6" />
          <Badge
            v-if="page.problems"
            class="w-4 h-4 p-0 flex justify-center absolute -top-1 -right-2"
            variant="destructive"
          >
            <span class="text-[10px]/[14px]">{{ page.problems }}</span>
          </Badge>
          <Badge v-if="page.infoBadge" class="w-4 h-4 p-0 flex justify-center absolute -top-1 -right-2" variant="info">
            <span class="text-[10px]/[14px]">{{ page.infoBadge }}</span>
          </Badge>
        </div>
        <span class="text-xs leading-5 font-medium text-center text-nowrap">{{ page.name }}</span>
      </NuxtLink>
      <div
        class="flex flex-col gap-2 items-center h-full justify-center transition duration-300 cursor-pointer active:bg-secondary active:text-secondary-foreground"
        :class="isMenuOpen ? 'bg-accent shadow-foreground shadow-[inset_0_-3px_0]' : ''"
        @click.stop="toggleMenu"
      >
        <div class="relative">
          <MenuIcon class="w-6 h-6" />
          <Badge
            v-if="menuExtendedProblems"
            v-show="!isMenuOpen"
            class="w-4 h-4 p-0 flex justify-center absolute -top-1 -right-2"
            variant="destructive"
          >
            <span class="text-[10px]/[14px]">{{ menuExtendedProblems }}</span>
          </Badge>
          <Badge
            v-else-if="menuExtendedNotifications"
            v-show="!isMenuOpen"
            class="w-4 h-4 p-0 flex justify-center absolute -top-1 -right-2"
            variant="info"
          >
            <span class="text-[10px]/[14px]">{{ menuExtendedNotifications }}</span>
          </Badge>
        </div>
        <span class="text-xs font-medium">Menu</span>
      </div>
    </div>
  </footer>
</template>

<script setup lang="ts">
import { EllipsisIcon, LogOutIcon, MenuIcon, MegaphoneIcon } from 'lucide-vue-next';
import { cn } from '@/lib/utils';

const props = defineProps<{ pages: Page[] }>();
const route = useRoute();
const { logOut } = useLogout();

const isMenuOpen = ref<boolean>(false);
const flatPages = computed(() => props.pages.flatMap((page) => (page.children ? [] : [page])));
const moreGroup = computed(() => props.pages.find((p) => p.children));
const hasMoreGroup = computed(() => !!moreGroup.value && (moreGroup.value.children?.length ?? 0) > 0);
const menu = computed(() => flatPages.value.slice(0, 3));
const menuExpanded = computed(() => flatPages.value.slice(3));
const menuExtendedProblems = computed(() => {
  return menuExpanded.value.reduce((acc, page) => acc + (page.problems || 0), 0);
});
const menuExtendedNotifications = computed(
  () => menuExpanded.value.find((page) => page.to.name === 'notifications')?.infoBadge ?? ''
);

const rMenuExpanded = ref<HTMLElement | null>(null);
const startY = ref(0);
const currentY = ref(0);
const isDragging = ref(false);
const animationFrame = ref<number | null>(null);

onMounted(() => {
  document.addEventListener('click', closeOnClickOutside);
});

onUnmounted(() => {
  document.removeEventListener('click', closeOnClickOutside);
});

const closeOnClickOutside = (event: MouseEvent) => {
  if (rMenuExpanded.value && !rMenuExpanded.value.contains(event.target as Node)) {
    isMenuOpen.value = false;
  }
};

const onTouchStart = (event: TouchEvent) => {
  startY.value = event.touches[0].clientY;
  isDragging.value = true;
  cancelAnimationFrame(animationFrame.value as number);
};

const onTouchMove = (event: TouchEvent) => {
  if (!isDragging.value) return;
  currentY.value = event.touches[0].clientY - startY.value;
  event.preventDefault();
};

const onTouchEnd = () => {
  if (currentY.value > 120) {
    animateBack();
    isMenuOpen.value = false;
  } else {
    animateBack();
  }
  isDragging.value = false;
  currentY.value = 0;
};

const animateBack = () => {
  let start = currentY.value;
  const step = () => {
    if (start > 0) {
      start -= 5;
      currentY.value = Math.max(start, 0);
      animationFrame.value = requestAnimationFrame(step);
    }
  };
  step();
};

function toggleMenu() {
  isMenuOpen.value = !isMenuOpen.value;
}

function closeMenu() {
  if (isMenuOpen.value) isMenuOpen.value = false;
}
</script>
