<template>
  <SidebarMenuItem
    class="flex gap-2 items-center h-10 justify-center transition duration-300 hover:bg-accent/40"
    :class="{ 'bg-accent shadow-foreground shadow-[inset_3px_0_0]': isCurrent(page) }"
    :style="indentStyle"
  >
    <SidebarMenuButton
      class="pl-4 w-full whitespace-nowrap flex h-10 hover:bg-transparent data-[active=true]:bg-transparent"
      :tooltip="page.name"
      :to="isRedirect ? page.to : undefined"
      :disabled="page.disabled"
      :is-active="isCurrent(page)"
      @click="emit('click', page)"
    >
      <div class="flex w-full items-center gap-2 min-w-0">
        <component :is="page.icon" class="w-4 h-4 shrink-0" />
        <span class="text-sm font-medium overflow-hidden whitespace-nowrap text-ellipsis">{{ page.name }}</span>
        <template v-if="isSlideOver || isCollapsibleGroup">
          <Spinner v-if="page.isLoading" class="ml-auto w-4 h-4 shrink-0" />
          <template v-else>
            <ChevronRightIcon v-if="isSlideOver" class="ml-auto w-4 h-4 shrink-0" />
            <ChevronDownIcon
              v-else
              class="ml-auto w-4 h-4 shrink-0 transition-transform duration-200"
              :class="open ? 'rotate-180' : ''"
            />
          </template>
        </template>
      </div>
      <Badge
        v-if="page.problems"
        class="w-4 h-4 p-0 flex justify-center absolute top-1 right-1 lg:relative lg:top-0 lg:right-0"
        variant="destructive"
      >
        <span class="text-[10px]/[14px] xs:text-xs">{{ page.problems }}</span>
      </Badge>
      <Badge
        v-if="page.infoBadge"
        class="w-4 h-4 p-0 flex justify-center absolute top-1 right-1 lg:relative lg:top-0 lg:right-0"
        variant="info"
      >
        <span class="text-[10px]/[14px] xs:text-xs">{{ page.infoBadge }}</span>
      </Badge>
    </SidebarMenuButton>
  </SidebarMenuItem>
</template>

<script setup lang="ts">
import { ChevronRightIcon, ChevronDownIcon } from 'lucide-vue-next';
import { useSidebar } from '@/components/ui/sidebar';
import { Spinner } from '~/assets/icons';

const isDesktop = useMediaQuery('(min-width: 1024px)');
const { state } = useSidebar();

const props = defineProps<{
  page: Page;
  open?: boolean;
  depth?: number;
}>();

const indentStyle = computed(() => {
  const depth = props.depth ?? 0;
  if (depth <= 0 || state.value === 'collapsed') return undefined;
  return { paddingLeft: `${depth * 0.25}rem` };
});

const isCollapsibleGroup = computed(() => !!props.page.children && !props.page.isSlideOver && isDesktop.value);
const isSlideOver = computed(() => !!props.page.children && props.page.isSlideOver && isDesktop.value);
const isRedirect = computed(() => !isDesktop.value || !props.page.children);

const emit = defineEmits<{ click: [page: Page] }>();

const { isCurrent } = useNavActive();
</script>
