export function getAccountProblem(alert: BannerAlerts): {
  title: string;
  subtitle: string;
  to: RouteLocationAsRelativeGeneric | null;
} {
  return (
    accountProblems[alert] ?? {
      title: snakeCaseToCapitalizedCase(alert),
      subtitle: '',
      to: null,
    }
  );
}
