<template>
  <SidebarProvider>
    <Sidebar collapsible="icon" class="border box-content bg-background">
      <SidebarHeader class="h-16 justify-center !py-0" />
      <AppSidebarContent :sidebar-pages />
      <SidebarFooter class="lg:pb-6">
        <SidebarMenu>
          <SidebarMenuItem id="sentry_report_a_bug" class="flex gap-2 items-center h-10 justify-center">
            <SidebarMenuButton class="pl-4 w-full" tooltip="Report a bug">
              <MegaphoneIcon class="h-4 w-4" />
              <span class="text-sm font-medium cursor-pointer">Report a Bug</span>
            </SidebarMenuButton>
          </SidebarMenuItem>
          <SidebarMenuItem class="flex gap-2 items-center justify-center">
            <SidebarUserMenu :notification-count="processedUnreadNotificationCount" />
          </SidebarMenuItem>
          <SidebarMenuItem class="gap-2 items-center h-6 justify-center absolute bottom-0 w-full hidden lg:flex">
            <SidebarMenuButton class="w-full cursor-default pointer-events-none" tooltip="Version" size="sm">
              <VersionBadge class="w-full pr-6" />
            </SidebarMenuButton>
          </SidebarMenuItem>
        </SidebarMenu>
      </SidebarFooter>
    </Sidebar>
    <SidebarInset :id="PTR_CONTENT_ID" class="bg-accent relative !h-svh !min-h-0 overflow-hidden">
      <div id="safe-area-top" />
      <OfflineBanner />
      <div class="flex-1 flex flex-col overflow-y-auto min-h-0">
        <AccountProblemNotifier
          v-if="!isChatPage"
          class="w-full max-w-screen-2xl mx-auto p-2 sm:px-4 lg:px-8 bg-red-50"
        />
        <section
          :class="
            cn('w-full max-w-screen-2xl mx-auto p-2 sm:p-4 lg:p-8 pb-28', {
              'p-0 sm:py-2 flex-1 min-h-0': isChatPage || isChatNestedPages,
              'pb-28': isChatPage && !isChatNestedPages,
            })
          "
        >
          <slot name="main" />
        </section>
        <MobileMenu v-if="!isChatNestedPages && !isMobileMenuHidden" :pages="filteredPages" />
        <div id="safe-area-bottom" />
      </div>
    </SidebarInset>
  </SidebarProvider>
</template>

<script setup lang="ts">
import { MegaphoneIcon } from 'lucide-vue-next';
import { cn } from '@/lib/utils';
import { useMobileRuntimeState } from '~/composables/mobile/useMobileRuntimeState';
import { useGetUnreadChatCount } from '~/composables/supabase/useGetUnreadChatsCount';
import { PTR_CONTENT_ID } from '~/plugins/pullToRefresh';
import { getUnreadNotificationsCount } from '~/client';

const route = useRoute();
const { isAuthenticated } = useUserRole();
const { isMobile } = useMobileForWeb();
const { isAppForeground } = useMobileRuntimeState();

const isChatPage = computed(() => route.name?.includes('chats'));
const isChatNestedPages = computed(() => route.name?.includes('chats-'));
const isMobileMenuHidden = computed(() => Boolean(route.meta?.hideMobileMenu));

const { data: unreadChatCount, refetch } = useQuery({
  key: () => ['unreadChatCount'],
  query: () => useGetUnreadChatCount(),
  enabled: () => isAuthenticated.value,
});

useTimeoutPoll(async () => {
  if (isMobile && !isAppForeground.value) return;
  if (isAuthenticated.value)
    await refetch().catch((error) => {
      console.error('Failed to fetch unread chat count:', unreadChatCount.value?.error, error);
    });
}, 15000);

const processedUnreadChatCount = computed(() => {
  if (!unreadChatCount.value?.data) return '';
  if (unreadChatCount.value.data > 9) return '9+';
  return unreadChatCount.value.data.toString();
});

const { data: unreadNotificationCount, refetch: refetchNotifications } = useQuery({
  key: () => ['unreadNotificationCount'],
  query: () => getUnreadNotificationsCount({ composable: '$fetch' }),
  enabled: () => isAuthenticated.value,
});

useTimeoutPoll(async () => {
  if (isMobile && !isAppForeground.value) return;
  if (isAuthenticated.value)
    await refetchNotifications().catch((error) => {
      console.error('Failed to fetch unread notification count:', error);
    });
}, 60000);

const processedUnreadNotificationCount = computed(() => {
  const count = unreadNotificationCount.value?.count;
  if (!count) return '';
  if (count > 9) return '9+';
  return count.toString();
});

const { filteredPages, sidebarPages } = useNavPages(processedUnreadChatCount, processedUnreadNotificationCount);
</script>

<style scoped lang="scss"></style>
