<template>
  <div class="flex items-center gap-2 min-w-0">
    <div class="relative shrink-0">
      <AvatarImageWrapper
        :src="avatarUrl ?? ''"
        :alt="fullName || 'User avatar'"
        :fallback="initials"
        :size="size"
        shape="circle"
      />
      <Badge
        v-if="problemCount"
        class="w-4 h-4 p-0 flex justify-center absolute -top-1 -right-1 pointer-events-none"
        variant="destructive"
      >
        <span class="text-[10px]/[14px]">{{ problemCount }}</span>
      </Badge>
      <Badge
        v-else-if="notificationCount"
        class="w-4 h-4 p-0 flex justify-center absolute -top-1 -right-1 pointer-events-none"
        variant="info"
      >
        <span class="text-[10px]/[14px]">{{ notificationCount }}</span>
      </Badge>
    </div>
    <div
      class="flex flex-col min-w-0 text-left"
      :class="{ 'group-data-[collapsible=icon]:hidden': hideTextWhenCollapsed }"
    >
      <span class="text-sm font-medium truncate">{{ fullName }}</span>
      <span class="text-xs text-muted-foreground truncate">{{ email }}</span>
    </div>
  </div>
</template>

<script setup lang="ts">
interface Props {
  size?: 'xs' | 'sm' | 'base' | 'lg';
  hideTextWhenCollapsed?: boolean;
  // Unread notification count shown as a badge on the avatar's top-right corner.
  // Only passed in the sidebar case; left undefined elsewhere (e.g. mobile menu).
  notificationCount?: string;
  // Account-alert count shown as a destructive badge on the avatar's top-right corner.
  // Takes priority over notificationCount — when present, it is shown instead of the
  // notification badge to surface account problems at a glance.
  problemCount?: string;
}

withDefaults(defineProps<Props>(), {
  size: 'xs',
  hideTextWhenCollapsed: false,
  notificationCount: undefined,
  problemCount: undefined,
});

const { fullName, email, initials, avatarUrl } = useUserRole();
</script>

<style scoped lang="scss"></style>
